{
  "status": "SUPPORTED",
  "task_summary": "The task requires identifying fasteners and a tool from storage, fastening a component at a marked location on a workbench, and leaving the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "OBJECT",
        "function": "Serves as the stable platform for the fastening operation.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "table",
          "desk"
        ],
        "required_properties": [
          "flat_surface",
          "stable"
        ]
      }
    ,
      {
        "id": "fastening_site",
        "entity_kind": "REGION",
        "function": "Designated area on the workbench where the fastening occurs.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "hole",
          "mounting_point",
          "marked_area"
        ],
        "required_properties": [
          "accessible",
          "specific_location"
        ]
      }
    ,
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "Hardware component used to secure the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "washer"
        ],
        "required_properties": [
          "threaded",
          "rigid"
        ]
      }
    ,
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Instrument used to drive or tighten the fastener.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "driver"
        ],
        "required_properties": [
          "grasping",
          "rotating"
        ]
      }
    ,
      {
        "id": "storage_container",
        "entity_kind": "OBJECT",
        "function": "Enclosed space searched for components and tools.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": [
          "cabinet",
          "drawer",
          "box"
        ],
        "required_properties": [
          "enclosed",
          "openable"
        ]
      }
    ]
  ,
      "functional_relations": [
      {
        "id": "situated_on",
        "relation": "spatial",
        "participant_roles": [
          "fastening_site",
          "workbench"
        ],
        "required": true
      }
    ,
        {
          "id": "compatible_with",
          "relation": "functional",
          "participant_roles": [
            "fastener",
            "fastening_site"
          ],
          "required": true
        }
      ,
        {
          "id": "used_for",
          "relation": "utilization",
          "participant_roles": [
            "fastening_tool",
            "fastener"
          ],
          "required": true
        }
      ,
        {
          "id": "holds",
          "relation": "containment",
          "participant_roles": [
            "storage_container",
            "fastener"
          ],
          "required": false
        }
      ]
    ,
      "operation_pairings": [
      {
        "id": "search_for_parts",
        "operation": "search_and_select",
        "participant_roles": [
          "storage_container",
          "fastener",
          "fastening_tool"
        ],
        "operation_count": 1
      }
    ,
        {
          "id": "perform_fastening",
          "operation": "apply_fastener",
          "participant_roles": [
            "fastening_tool",
            "fastener",
            "fastening_site"
          ],
          "operation_count": 1
        }
      ,
        {
          "id": "place_equipment",
          "operation": "deposit",
          "participant_roles": [
            "fastening_tool",
            "workbench"
          ],
          "operation_count": 1
        }
      ]
    }
  ,
    "observation_guidance": {
      "visible_candidates_per_role": {
        "workbench": [
          {
            "label": "wooden_table",
            "visual_description": "Wooden desk with two drawers underneath"
          }
        ]
      ,
        "fastening_site": [
          {
            "label": "yellow_object",
            "visual_description": "Small yellow and blue rectangular object sitting on the table surface"
          }
        ]
      ,
        "storage_container": [
          {
            "label": "cabinet",
            "visual_description": "Tall blue cabinet standing on the right side of the table"
          }
        ,
          {
            "label": "left_drawer",
            "visual_description": "Drawer on the left side under the table"
          }
        ,
          {
            "label": "right_drawer",
            "visual_description": "Drawer on the right side under the table"
          }
        ]
      }
    ,
      "inspectable_regions": [
      {
        "id": "cabinet_door",
        "label": "Cabinet Door",
        "visual_description": "Closed blue door of the tall cabinet",
        "reason": "Closed storage structure likely containing tools or parts."
      }
    ,
        {
          "id": "left_drawer",
          "label": "Left Drawer",
          "visual_description": "Closed drawer with handle on the left",
          "reason": "Closed drawer structure likely containing small components."
        }
      ,
        {
          "id": "right_drawer",
          "label": "Right Drawer",
          "visual_description": "Closed drawer with handle on the right",
          "reason": "Closed drawer structure likely containing small components."
        }
      ]
    ,
      "inspection_order": [
        "cabinet_door",
        "left_drawer",
        "right_drawer"
      ]
    }
  ,
    "unsupported_reason": ""
  ,
    "schema_version": 3
}
